class Solution:
    def buildTree(self, inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
        pos = {v: i for i, v in enumerate(inorder)}; st = postorder[:]
        def go(lo, hi):
            if lo > hi: return None
            v = st.pop(); m = pos[v]
            n = TreeNode(v); n.right = go(m + 1, hi); n.left = go(lo, m - 1)
            return n
        return go(0, len(inorder) - 1)

