function buildTree(inorder, postorder) {
  const go = (ino, post) => {
    if (!ino.length) return null;
    const v = post[post.length - 1], m = ino.indexOf(v);
    return new TreeNode(v, go(ino.slice(0, m), post.slice(0, m)), go(ino.slice(m + 1), post.slice(m, post.length - 1)));
  };
  return go(inorder, postorder);
}
